using KernelOS.Core; using KernelOS.Core.Conversation; using KernelOS.Core.Kai; using KernelOS.Core.Rag; using Microsoft.Extensions.Options;
namespace KernelOS.Infrastructure.Kai;
public sealed class KaiAgent(IConversationContextBuilder conversation,IKaiIntentRouter router,IRagPipeline rag,IChatModel chat,IOptions<KaiOptions> options):IKaiAgent
{ private readonly KaiOptions options=options.Value;
 public async Task<KaiResponse> HandleAsync(KaiRequest request,CancellationToken cancellationToken=default){ var token=cancellationToken; if(token.IsCancellationRequested)return new(KaiStatus.Cancelled,KaiMode.Auto); if(string.IsNullOrWhiteSpace(request.Message)||request.Message.Length>options.MaxMessageCharacters||!Enum.IsDefined(request.PreferredMode))return new(KaiStatus.InvalidRequest,KaiMode.Auto); var context=await conversation.BuildAsync(new(request.History??[],request.Message),token); if(context.Status==ConversationContextStatus.Cancelled)return new(KaiStatus.Cancelled,KaiMode.Auto); if(context.Status==ConversationContextStatus.InvalidRequest||context.Status==ConversationContextStatus.Failed)return new(KaiStatus.Failed,KaiMode.Auto); var decision=router.Route(request.Message,request.PreferredMode); if(decision.Mode==KaiMode.Rag){var result=await rag.AnswerAsync(new(request.Message),token); if(result.Status==RagStatus.NoContext&&request.PreferredMode==KaiMode.Auto&&options.AllowAutoRagFallbackToChat)return await Chat(context,request,decision,[new("KAI_RAG_NO_CONTEXT_FALLBACK","No retrieved context; used chat.")],token); return new(Map(result.Status),KaiMode.Rag,result.Answer,result.Citations,result.Warnings?.Select(w=>new KaiWarning(w.Code,w.Message)).ToArray(),result.Model,decision);} if(decision.Mode==KaiMode.Planner)return new(KaiStatus.Failed,KaiMode.Planner,Warnings:[new("KAI_PLANNER_UNAVAILABLE","Planner execution is outside Kai Agent v1.")],Decision:decision); return await Chat(context,request,decision,null,token); }
 private async Task<KaiResponse> Chat(ConversationContextResult context,KaiRequest request,KaiDecision decision,IReadOnlyList<KaiWarning>? warnings,CancellationToken token){var history=context.Pack?.Items.Select(i=>new ChatMessage(i.Role==ConversationRole.User?"user":"assistant",i.Content)).ToArray();var response=await chat.SendAsync(new ChatRequest(request.Message!,history:history),token);if(token.IsCancellationRequested||string.Equals(response.Error,"cancelled",StringComparison.Ordinal))return new(KaiStatus.Cancelled,KaiMode.Chat);return response.Success?new(context.Status==ConversationContextStatus.PartialSuccess?KaiStatus.PartialSuccess:KaiStatus.Success,KaiMode.Chat,response.Message,Warnings:warnings,Model:response.Model,Decision:decision):new(KaiStatus.ProviderUnavailable,KaiMode.Chat,Model:response.Model,Decision:decision);}
 private static KaiStatus Map(RagStatus status)=>status switch{RagStatus.Success=>KaiStatus.Success,RagStatus.PartialSuccess=>KaiStatus.PartialSuccess,RagStatus.NoContext=>KaiStatus.NoContext,RagStatus.InvalidRequest=>KaiStatus.InvalidRequest,RagStatus.ProviderUnavailable=>KaiStatus.ProviderUnavailable,RagStatus.Cancelled=>KaiStatus.Cancelled,_=>KaiStatus.Failed}; }
